B.a9O=new A.ai("Insuline + G50%",B.E,B.R,"10 U insuline + 50 ml G50%","IV sur 15 min","R\xe9duit K\u207a de 0.5\u20131 mEq/L en 15\u201330 min. Dur\xe9e d'action 4\u20136h. Surveiller glyc\xe9mie.",!0)
B.abf=new A.ai("Salbutamol (IV/n\xe9bulis\xe9)",B.E,B.S,"10\u201320 mg n\xe9bulis\xe9","N\xe9bulis\xe9 ou IV","R\xe9duit K\u207a de 0.5\u20131 mEq/L suppl\xe9mentaire. En compl\xe9ment insuline. Non efficace chez dialys\xe9s.",!1)
B.aaN=new A.ai("Bicarbonate de Sodium",B.E,B.S,"50\u2013100 mEq IV","IV lent (30 min)","Si pH<7.2 + acidose m\xe9tabolique. Effet modeste sur K\u207a. CI si surcharge sodique ou alcalose.",!1)
B.a9S=new A.ai("Furos\xe9mide",B.E,B.S,"40\u2013200 mg IV","IV","Surcharge vol\xe9mique av\xe9r\xe9e UNIQUEMENT. Ne pr\xe9vient pas la dialyse (KDIGO 2012).",!1)
