B.abp=new A.ai("Glucose 50% (G50%)",B.E,B.S,"50 ml IV","IV lent","Hypoglyc\xe9mie <0.7 g/L. Puis G10% IVSE. Monitoring glyc\xe9mique q1h.",!0)
